import { toProject } from "./_mappers";
import type {
  CreateProjectInput,
  ListProjectsInput,
  UpdateProjectInput,
} from "@/schemas/project";
import type { ArchiveScope, OrgId, Page, ProjectId, UserId } from "@/types/common";
import type { Project, ProjectStats } from "@/types/project";
import type { SQL } from "drizzle-orm";

/**
 * Projects a non-admin actor may see: every non-private project, plus private
 * ones they lead or have been added to. Admins, owners and platform staff skip
 * this predicate — callers pass no user id in that case.
 */
export function visibleProjectClause(orgId: OrgId, userId: UserId): SQL {
  const membership = getDb()
    .select({ projectId: projectMembers.projectId })
    .from(projectMembers)
    .where(
      and(
        orgPredicate(projectMembers.orgId, orgId),
        eq(projectMembers.userId, userId),
      ),
    );

  const clause = or(
    ne(projects.visibility, "private"),
    eq(projects.leadId, userId),
    inArray(projects.id, membership),
  );

  return clause ?? sql`1 = 1`;
}

/** Issues whose project passes `visibleProjectClause` for `userId`. */
export function issuesInVisibleProjects(orgId: OrgId, userId: UserId): SQL {
  return inArray(
    issues.projectId,
    getDb()
      .select({ id: projects.id })
      .from(projects)
      .where(and(orgPredicate(projects.orgId, orgId), visibleProjectClause(orgId, userId))),
  );
}

