import { wouldExceedLimit } from "@/config/plan-limits";
import { emit } from "@/lib/event-bus";
import { assertCan } from "@/lib/permissions";
import { projectKeyFromName, uniqueSlug } from "@/lib/slug";
import { assertNotArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as projectMemberRepo from "@/server/repositories/project-member-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import {
  actorEnvelope,
  NotFoundError,
  orgResource,
  projectResource,
  requireFound,
} from "./_support";
import type {
  ArchiveProjectInput,
  CreateProjectInput,
  ListProjectsInput,
  UpdateProjectInput,
} from "@/schemas/project";
import type { OrgId, Page, ProjectId, UserId } from "@/types/common";
import type { Actor } from "@/types/member";
import { hasRoleAtLeast } from "@/types/member";
import type { Project, ProjectWithStats } from "@/types/project";

/**
 * Whether `actor` may see `project`. `org` and `public` projects are visible
 * to every actor. A `private` project is visible only to an admin or owner of
 * its organization, platform staff, the project's lead, or an explicit member.
 * Membership and lead are read on each call, so a change takes effect immediately.
 */
export async function canViewProject(
  actor: Actor,
  project: Project,
): Promise<boolean> {
  if (project.visibility !== "private") return true;
  if (actor.isPlatformStaff === true) return true;
  if (
    actor.orgId === project.orgId &&
    hasRoleAtLeast(actor.role, "admin")
  ) {
    return true;
  }
  if (project.leadId === actor.userId) return true;
  return projectMemberRepo.isProjectMember(
    project.orgId,
    project.id,
    actor.userId,
  );
}

/**
 * User id to narrow project and issue listings to, or `undefined` when the
 * actor sees every private project (admin, owner, or platform staff). Lead
 * and membership are applied in the query for the returned id.
 */
export function listingViewerId(actor: Actor): UserId | undefined {
  if (actor.isPlatformStaff === true) return undefined;
  if (hasRoleAtLeast(actor.role, "admin")) return undefined;
  return actor.userId;
}

/** Throws `NotFoundError` when a private project must behave as if missing. */
async function requireViewable(
  actor: Actor,
  project: Project,
  id: string,
): Promise<void> {
  if (!(await canViewProject(actor, project))) {
    throw new NotFoundError("Project", id);
  }
}

