/**
 * A private project the actor cannot see hides every issue in it. The throw
 * matches a missing row so the two cases stay indistinguishable.
 */
async function assertIssueProjectVisible(
  actor: Actor,
  issue: Issue,
  entity: string,
  id: string,
): Promise<void> {
  const project = await projectRepo.findProjectById(issue.orgId, issue.projectId);
  if (project !== null && !(await canViewProject(actor, project))) {
    throw new NotFoundError(entity, id);
  }
}

