/**
 * Temporary coverage for private-project visibility. Deleted after the run.
 */
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
vi.mock("@/lib/rate-limit", async () => (await import("../server/_support/doubles/misc")).rateLimitModule);

import { PermissionDeniedError } from "@/lib/permissions";
import { TenantScopeError } from "@/lib/tenant";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as projectMemberRepo from "@/server/repositories/project-member-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import { NotFoundError } from "@/server/services/_support";
import * as projectService from "@/server/services/project-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { Issue } from "@/types/issue";
import type { Actor } from "@/types/member";
import type { Project } from "@/types/project";

let cleanup: () => void;
let tenant: Tenant;
let secret: Project;
let secretIssue: Issue;
let visibleIssue: Issue;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("privacy");

  secret = await projectService.createProject(tenant.actors.admin, {
    orgId: tenant.org.id,
    name: "Secret Lab",
    slug: "secret-lab",
    key: "SEC",
    description: null,
    visibility: "private",
    leadId: null,
    color: "#6366f1",
    targetDate: null,
  });

  secretIssue = await issueService.createIssue(
    tenant.actors.admin,
    issueInput(tenant.org.id, secret.id, { title: "Classified bug" }),
  );

  visibleIssue = await issueService.createIssue(
    tenant.actors.member,
    issueInput(tenant.org.id, tenant.project.id, { title: "Public bug" }),
  );
});

afterAll(() => {
  cleanup();
});

function staffViewer(): Actor {
  return { ...tenant.actors.viewer, isPlatformStaff: true };
}

describe("canViewProject", () => {
  it("lets admins, owners, staff, leads and members see a private project", async () => {
    expect(await projectService.canViewProject(tenant.actors.admin, secret)).toBe(true);
    expect(await projectService.canViewProject(tenant.actors.owner, secret)).toBe(true);
    expect(await projectService.canViewProject(staffViewer(), secret)).toBe(true);
    expect(await projectService.canViewProject(tenant.actors.member, secret)).toBe(false);
    expect(await projectService.canViewProject(tenant.actors.viewer, secret)).toBe(false);

    expect(
      await projectService.canViewProject(tenant.actors.member, {
        ...secret,
        leadId: tenant.actors.member.userId,
      }),
    ).toBe(true);

    expect(await projectService.canViewProject(tenant.actors.member, tenant.project)).toBe(true);
    expect(
      await projectService.canViewProject(tenant.actors.viewer, {
        ...tenant.project,
        visibility: "public",
      }),
    ).toBe(true);
  });

  it("picks up membership and lead changes immediately", async () => {
    expect(await projectService.canViewProject(tenant.actors.member, secret)).toBe(false);

    await projectMemberRepo.addProjectMember(
      tenant.org.id,
      secret.id,
      tenant.actors.member.userId,
    );
    expect(await projectService.canViewProject(tenant.actors.member, secret)).toBe(true);

    await projectMemberRepo.removeProjectMember(
      tenant.org.id,
      secret.id,
      tenant.actors.member.userId,
    );
    expect(await projectService.canViewProject(tenant.actors.member, secret)).toBe(false);

    const led = await projectService.updateProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      projectId: secret.id,
      leadId: tenant.actors.viewer.userId,
    });
    secret = led;
    expect(await projectService.canViewProject(tenant.actors.viewer, secret)).toBe(true);

    const cleared = await projectService.updateProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      projectId: secret.id,
      leadId: null,
    });
    secret = cleared;
    expect(await projectService.canViewProject(tenant.actors.viewer, secret)).toBe(false);
  });
});

describe("private project hiding", () => {
  it("404s lookups and leaves listings without the project", async () => {
    await expect(
      projectService.getProject(tenant.actors.member, tenant.org.id, secret.slug),
    ).rejects.toBeInstanceOf(NotFoundError);

    await expect(
      issueService.getIssue(tenant.actors.member, tenant.org.id, secretIssue.id),
    ).rejects.toBeInstanceOf(NotFoundError);

    await expect(
      issueService.getBoard(tenant.actors.member, tenant.org.id, secret.id),
    ).rejects.toBeInstanceOf(NotFoundError);

    await expect(
      commentService.getThread(tenant.actors.member, tenant.org.id, secretIssue.id),
    ).rejects.toBeInstanceOf(NotFoundError);

    const projects = await projectService.listProjects(tenant.actors.member, {
      orgId: tenant.org.id,
      limit: 25,
      cursor: null,
    });
    expect(projects.items.map((row) => row.project.id)).not.toContain(secret.id);
    expect(projects.total).toBe(1);

    const asAdmin = await projectService.listProjects(tenant.actors.admin, {
      orgId: tenant.org.id,
      limit: 25,
      cursor: null,
    });
    expect(asAdmin.items.map((row) => row.project.id)).toContain(secret.id);
    expect(asAdmin.total).toBe(2);

    const issues = await issueService.listIssues(tenant.actors.member, {
      orgId: tenant.org.id,
      limit: 25,
      cursor: null,
    });
    expect(issues.items.map((issue) => issue.id)).not.toContain(secretIssue.id);
    expect(issues.items.map((issue) => issue.id)).toContain(visibleIssue.id);
    expect(issues.total).toBe(1);

    const adminIssues = await issueService.listIssues(tenant.actors.admin, {
      orgId: tenant.org.id,
      limit: 25,
      cursor: null,
    });
    expect(adminIssues.total).toBe(2);
  });

  it("refuses writes without changing rows, including for viewers", async () => {
    await expect(
      issueService.createIssue(
        tenant.actors.member,
        issueInput(tenant.org.id, secret.id, { title: "Should not land" }),
      ),
    ).rejects.toBeInstanceOf(NotFoundError);
    expect(await issueRepo.countIssues(tenant.org.id, secret.id)).toBe(1);

    await expect(
      issueService.createIssue(
        tenant.actors.viewer,
        issueInput(tenant.org.id, secret.id, { title: "Viewer probe" }),
      ),
    ).rejects.toBeInstanceOf(NotFoundError);

    await expect(
      issueService.updateIssue(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: secretIssue.id,
        title: "Renamed secretly",
      }),
    ).rejects.toBeInstanceOf(NotFoundError);

    await expect(
      issueService.changeIssueStatus(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: secretIssue.id,
        status: "done",
      }),
    ).rejects.toBeInstanceOf(NotFoundError);

    await expect(
      issueService.moveIssue(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: secretIssue.id,
        toStatus: "todo",
        toIndex: 0,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);

    await expect(
      issueService.assignIssue(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: secretIssue.id,
        assigneeId: tenant.actors.member.userId,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);

    await expect(
      issueService.archiveIssue(tenant.actors.member, tenant.org.id, secretIssue.id),
    ).rejects.toBeInstanceOf(NotFoundError);

    const stored = await issueRepo.findIssueById(tenant.org.id, secretIssue.id);
    expect(stored?.title).toBe("Classified bug");
    expect(stored?.status).toBe("backlog");
    expect(stored?.assigneeId).toBeNull();
    expect(stored?.archivedAt).toBeNull();

    const comment = await commentService.createComment(tenant.actors.admin, {
      orgId: tenant.org.id,
      issueId: secretIssue.id,
      body: "stay put",
      parentId: null,
      mentionedUserIds: [],
    });

    await expect(
      commentService.createComment(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: secretIssue.id,
        body: "nope",
        parentId: null,
        mentionedUserIds: [],
      }),
    ).rejects.toBeInstanceOf(NotFoundError);

    await expect(
      commentService.updateComment(tenant.actors.member, {
        orgId: tenant.org.id,
        commentId: comment.id,
        body: "edited",
      }),
    ).rejects.toBeInstanceOf(NotFoundError);

    await expect(
      commentService.deleteComment(tenant.actors.member, {
        orgId: tenant.org.id,
        commentId: comment.id,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);

    const storedComment = await commentRepo.findCommentById(tenant.org.id, comment.id);
    expect(storedComment?.body).toBe("stay put");
    expect(storedComment?.archivedAt).toBeNull();

    await expect(
      projectService.updateProject(tenant.actors.member, {
        orgId: tenant.org.id,
        projectId: secret.id,
        name: "Renamed lab",
      }),
    ).rejects.toBeInstanceOf(NotFoundError);

    await expect(
      projectService.archiveProject(tenant.actors.member, {
        orgId: tenant.org.id,
        projectId: secret.id,
        archiveIssues: true,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);

    const storedProject = await projectRepo.findProjectById(tenant.org.id, secret.id);
    expect(storedProject?.name).toBe("Secret Lab");
    expect(storedProject?.archivedAt).toBeNull();
    expect(await issueRepo.countIssues(tenant.org.id, secret.id)).toBe(1);

    await projectService.archiveProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      projectId: secret.id,
      archiveIssues: false,
    });

    await expect(
      projectService.restoreProject(tenant.actors.member, tenant.org.id, secret.id),
    ).rejects.toBeInstanceOf(NotFoundError);

    const archived = await projectRepo.findProjectById(tenant.org.id, secret.id);
    expect(archived?.archivedAt).not.toBeNull();

    await projectService.restoreProject(tenant.actors.admin, tenant.org.id, secret.id);
  });

  it("still permission-checks actors who can see the project", async () => {
    await expect(
