    expect(storedComment?.body).toBe("stay put");
    expect(storedComment?.archivedAt).toBeNull();

    await expect(
      projectService.updateProject(tenant.actors.member, {
        orgId: tenant.org.id,
        projectId: secret.id,
        name: "Renamed lab",
      }),
    ).rejects.toBeInstanceOf(NotFoundError);

    await expect(
      projectService.archiveProject(tenant.actors.member, {
        orgId: tenant.org.id,
        projectId: secret.id,
        archiveIssues: true,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);

    const storedProject = await projectRepo.findProjectById(tenant.org.id, secret.id);
    expect(storedProject?.name).toBe("Secret Lab");
    expect(storedProject?.archivedAt).toBeNull();
    expect(await issueRepo.countIssues(tenant.org.id, secret.id)).toBe(1);

    await projectService.archiveProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      projectId: secret.id,
      archiveIssues: false,
    });

    await expect(
      projectService.restoreProject(tenant.actors.member, tenant.org.id, secret.id),
    ).rejects.toBeInstanceOf(NotFoundError);

    const archived = await projectRepo.findProjectById(tenant.org.id, secret.id);
    expect(archived?.archivedAt).not.toBeNull();

    await projectService.restoreProject(tenant.actors.admin, tenant.org.id, secret.id);
  });

  it("still permission-checks actors who can see the project", async () => {
    await expect(
      issueService.createIssue(
        tenant.actors.viewer,
        issueInput(tenant.org.id, tenant.project.id, { title: "Viewer on org project" }),
      ),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
  });

  it("keeps cross-tenant access a scope error", async () => {
    const other = await createTenant("privacyother");
    await expect(
      issueService.getIssue(other.actors.owner, tenant.org.id, secretIssue.id),
    ).rejects.toBeInstanceOf(TenantScopeError);
  });

  it("shows a private project to a member once they are added, and hides it again", async () => {
    await projectMemberRepo.addProjectMember(
      tenant.org.id,
      secret.id,
      tenant.actors.member.userId,
    );

    const found = await projectService.getProject(
      tenant.actors.member,
      tenant.org.id,
      secret.slug,
    );
    expect(found.project.id).toBe(secret.id);

    const page = await issueService.listIssues(tenant.actors.member, {
      orgId: tenant.org.id,
      limit: 1,
      cursor: null,
    });
    expect(page.total).toBe(2);

    await projectMemberRepo.removeProjectMember(
      tenant.org.id,
      secret.id,
      tenant.actors.member.userId,
    );

    await expect(
      projectService.getProject(tenant.actors.member, tenant.org.id, secret.slug),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("pages only visible issues", async () => {
    await issueService.createIssue(
      tenant.actors.admin,
      issueInput(tenant.org.id, secret.id, { title: "Second classified" }),
    );
    await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Second visible" }),
    );

    const page = await issueService.listIssues(tenant.actors.member, {
      orgId: tenant.org.id,
      limit: 1,
      cursor: null,
    });
    expect(page.total).toBe(2);
    expect(page.items).toHaveLength(1);
    expect(page.items[0]?.projectId).toBe(tenant.project.id);
    expect(page.nextCursor).not.toBeNull();
  });
});
